import{_ as r,C as n,o as l,c as h,a6 as i,E as a,j as s,a as o}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"Web Cache Deception","description":"Path mapping, delimiters, origin and cache normalisation, and exact-match cache rules.","frontmatter":{"title":"Web Cache Deception","description":"Path mapping, delimiters, origin and cache normalisation, and exact-match cache rules."},"headers":[],"relativePath":"cache-deception/index.md","filePath":"cache-deception/index.md"}'),d={name:"cache-deception/index.md"};function p(m,e,u,g,b,f){const t=n("LabGroup"),c=n("TopicComplete");return l(),h("div",null,[e[0]||(e[0]=i(`<h1 id="web-cache-deception" tabindex="-1">Web Cache Deception <a class="header-anchor" href="#web-cache-deception" aria-label="Permalink to &quot;Web Cache Deception&quot;">​</a></h1><p class="wd-section-lede">Cache deception is the inverse of cache poisoning. Poisoning puts attacker data into a shared cache; deception tricks the cache into storing a <em>victim&#39;s private response</em> as a public object. The exploit is a URL that looks static to the cache and dynamic to the origin.</p><div class="wd-callout"><p><strong>The model.</strong> A cache decides what to store from the URL and response headers. The origin decides what to return from the path. If those two parsers disagree about which resource the path names, the private response can be stored under a public key.</p></div><h2 id="the-mismatch" tabindex="-1">The mismatch <a class="header-anchor" href="#the-mismatch" aria-label="Permalink to &quot;The mismatch&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /my-account/foo.js</span></span>
<span class="line"><span>cache:  path ends .js, cacheable static asset → MISS, forward</span></span>
<span class="line"><span>origin: /my-account exists → return the victim&#39;s account page</span></span>
<span class="line"><span>cache:  store body under /my-account/foo.js</span></span>
<span class="line"><span>attacker: GET /my-account/foo.js → victim&#39;s account page</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Three conditions are required:</p><ol><li>the cache stores the response under a key the attacker can request;</li><li>the origin returns private data for that path;</li><li>the victim&#39;s browser is induced to request the crafted URL.</li></ol><h2 id="path-mapping" tabindex="-1">Path mapping <a class="header-anchor" href="#path-mapping" aria-label="Permalink to &quot;Path mapping&quot;">​</a></h2><p>The simplest variant appends a static-looking suffix to a private route. The cache treats the URL as an asset; the framework routes on the prefix.</p>`,9)),a(t,{ids:"cache-deception-lab-wcd-exploiting-path-mapping"}),e[1]||(e[1]=i('<h2 id="delimiters" tabindex="-1">Delimiters <a class="header-anchor" href="#delimiters" aria-label="Permalink to &quot;Delimiters&quot;">​</a></h2><p>Different layers treat <code>;</code>, <code>?</code>, <code>#</code>, <code>.</code>, and <code>%00</code> as path delimiters. A delimiter that the origin ignores but the cache uses (or vice versa) splits the key from the route.</p>',2)),a(t,{ids:"cache-deception-lab-wcd-exploiting-path-delimiters"}),e[2]||(e[2]=i('<details class="details custom-block"><summary>🔬 Under the Hood: normalisation is the vulnerability</summary><p>Both cache and origin normalise paths, but not necessarily the same way:</p><ul><li>repeated slashes (<code>//my-account</code>)</li><li>dot segments (<code>/my-account/../my-account</code>)</li><li>percent-encoded characters (<code>%2f</code>, <code>%2e</code>)</li><li>trailing dots or spaces on Windows origins</li><li>path parameters (<code>;jsessionid=...</code>)</li></ul><p>If the cache keys on the raw path while the origin normalises it, <code>/my-account%2f..%2fstatic.js</code> can map to a public cache key and a private origin route. Conversely, if the cache normalises and the origin does not, the attacker can request the normalised key to retrieve a response cached under a different raw path.</p></details><h2 id="origin-vs-cache-normalisation" tabindex="-1">Origin vs cache normalisation <a class="header-anchor" href="#origin-vs-cache-normalisation" aria-label="Permalink to &quot;Origin vs cache normalisation&quot;">​</a></h2><p>The two labs below test the direction of the mismatch:</p><ul><li><strong>Origin normalisation:</strong> the origin collapses dot segments; the cache keys the raw path.</li><li><strong>Cache normalisation:</strong> the cache collapses them; the origin routes on the raw path.</li></ul>',4)),a(t,{ids:"cache-deception-lab-wcd-exploiting-origin-server-normalization, cache-deception-lab-wcd-exploiting-cache-server-normalization"}),e[3]||(e[3]=s("h2",{id:"exact-match-rules",tabindex:"-1"},[o("Exact-match rules "),s("a",{class:"header-anchor",href:"#exact-match-rules","aria-label":'Permalink to "Exact-match rules"'},"​")],-1)),e[4]||(e[4]=s("p",null,[o("Some caches only store responses for URL patterns that look static. If the rule is exact ("),s("code",null,"/resources/*.js"),o("), the attacker needs a path that satisfies the rule while the origin still resolves the private route — often through an extension or a path parameter.")],-1)),a(t,{ids:"cache-deception-lab-wcd-exploiting-exact-match-cache-rules"}),e[5]||(e[5]=i('<details class="details custom-block"><summary>⚙️ Engine Variations: cache implementations</summary><ul><li><strong>Cloudflare:</strong> caches by default on file extensions; query strings are part of the key in most plans.</li><li><strong>Akamai:</strong> configurable rules per path pattern; <code>Vary</code> handling differs.</li><li><strong>Varnish:</strong> <code>vcl_hash</code> decides the key; the default includes host and URL.</li><li><strong>Nginx proxy_cache:</strong> <code>proxy_cache_key</code> is configurable and often omits query strings by mistake.</li><li><strong>CDNs with &quot;cache everything&quot;:</strong> private HTML becomes cacheable unless <code>Cache-Control: private</code> is respected.</li></ul><p>The deception succeeds when the deployment&#39;s rule for &quot;cacheable&quot; is broader than the application&#39;s rule for &quot;public&quot;.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Mark authenticated responses <code>Cache-Control: private, no-store</code>. Do not let the cache infer cacheability from the extension; require explicit <code>Cache-Control: public</code> for shared caching. Normalise and validate paths before routing, and make cache and origin use the same normalisation. Test private routes with appended static suffixes.</p></div>',2)),a(c,{"topic-id":"web-cache-deception",label:"Mark web cache deception complete"})])}const x=r(d,[["render",p]]);export{v as __pageData,x as default};
